 void selectCalendars(String id)throws Exception{ArrayList<String> ids=new ArrayList<>(),labels=new ArrayList<>();try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id","calendar_displayName","account_name"},"visible=1",null,null)){if(c!=null)while(c.moveToNext()){ids.add(c.getString(0));labels.add(c.getString(1)+" · "+c.getString(2));}}if(ids.isEmpty()){reply(id,null,"No synced calendars were found. Enable calendar sync for your Google account in phone settings.");return;}Set<String> saved=getPreferences(0).getStringSet("calendars",new HashSet<>());boolean[] checked=new boolean[ids.size()];for(int i=0;i<ids.size();i++)checked[i]=saved.contains(ids.get(i));new AlertDialog.Builder(this).setTitle("Calendars for Nudge").setMultiChoiceItems(labels.toArray(new String[0]),checked,(dialog,which,isChecked)->checked[which]=isChecked).setPositiveButton("Connect",(dialog,which)->{try{Set<String> chosen=new HashSet<>();for(int i=0;i<ids.size();i++)if(checked[i])chosen.add(ids.get(i));getPreferences(0).edit().putStringSet("calendars",chosen).apply();reply(id,new JSONObject().put("events",calendarEvents()),null);}catch(Exception e){reply(id,null,"Calendar sync could not finish.");}}).setNegativeButton("Cancel",(d,w)->reply(id,null,"Calendar selection cancelled.")).setOnCancelListener(d->reply(id,null,"Calendar selection cancelled.")).show();}
